// Assemble the Wagtail Animal Clinic theme (6 Divi 5 pages for a veterinary clinic and grooming studio) into one pack. Unlike create-real-estate-pack.ts the pages are NOT
// generated by the pipeline's Claude workers: they are composed by the AI Editor for
// Divi 5 plugin from its section recipes (design language organic-warm + a style kit,
// validated by the real LayoutGate) in the validator repo:
//   php scripts/theme-packs/build.php wagtail       -> dist/theme-packs/wagtail/<role>.json
// and then run through every downstream gate here (validate, stock photos, design lint,
// mobile stacking, dedupe, SEO, real Divi render, critics, ingest).
//
//   npm run dev            # in another shell (ingest target)
//   set -a && . ./.env.local && set +a && WAG_DIR=<dir with the six json files> npx tsx scripts/create-wagtail-pack.ts
// Smoke test: THEME_ONLY_ROLES=home.
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { eq, inArray } from 'drizzle-orm';
import { db } from '@/db/client';
import { packs, packLayouts, layouts } from '@/db/schema';
import { buildThemeDeps } from '@/pipeline/deps';
import { runThemePack, themePageSlug, type ThemeSpec, type ThemePage } from '@/pipeline/theme';
import type { Brief } from '@/pipeline/compose';

const DIR = process.env.WAG_DIR ?? '../Divi 5 Deterministic Validator/dist/theme-packs/wagtail';

const BRIEF: Brief = {
  businessType: 'service/agency',
  businessName: 'Wagtail Animal Clinic',
  tagline: 'Gentle care for your whole pack',
  audience: 'pet owners who want a calm, friendly vet clinic that explains everything and makes anxious pets feel safe',
  conversionGoal: 'book a first visit',
  primaryCta: 'Book a visit',
  accentColorHex: '#FF7AA5',
  voice: 'warm, plain-spoken and a little playful. Short sentences, specific details, no hype and no pet-industry clichés.',
  palette: { primary: '#ff7aa5', secondary: '#7a5cff', tint: '#fff7ec', dark: '#2b2340', heading: '#2b2340', body: '#4a4260' },
  designNotes: 'Playful-pastel design language: a different soft pastel behind each section, very round shapes, Fredoka rounded headlines, Nunito body and big friendly pill buttons.',
};

const BRAND_FACTS =
  'Wagtail Animal Clinic, 310 Barton Springs Road, Austin, TX 78704. Phone (512) 555-0127. hello@wagtailclinic.com. ' +
  'Sample copy: names, prices and reviews are examples to replace.';

const ROLES: { role: string; roleLabel: string }[] = [
  { role: 'home', roleLabel: 'Home' },
  { role: 'services', roleLabel: 'Services' },
  { role: 'plans', roleLabel: 'Wellness Plans' },
  { role: 'vets', roleLabel: 'Our Vets' },
  { role: 'clinic', roleLabel: 'The Clinic' },
  { role: 'contact', roleLabel: 'Contact' },
];

const PAGES: ThemePage[] = ROLES.map((r) => ({
  ...r,
  flow: [],
  precomposed: readFileSync(`${DIR}/${r.role}.json`, 'utf8'),
}));

const SPEC: ThemeSpec = { niche: 'veterinary', style: 'playful', color: 'pink', brief: BRIEF, brandFacts: BRAND_FACTS, pages: PAGES };

const PACK_SLUG = 'wagtail-veterinary-clinic-theme';
const PACK_TITLE = 'Wagtail: Veterinary Clinic & Grooming Theme (6 Pages)';
const PRICE_CENTS = 1200;
const DESCRIPTION =
  'A complete six-page Divi 5 website for a veterinary clinic, animal hospital or pet grooming studio, ready to make your ' +
  'own. Home, Services, Wellness Plans, Our Vets, The Clinic and Contact share one cheerful, friendly identity: a soft ' +
  'pastel behind every section, rounded Fredoka headlines, big pill buttons and real photography of pets and their people. ' +
  'Every section is built from proven, validated recipes and a single design language and style kit, so buttons, ' +
  'accordions, forms and type match on every page, on desktop, tablet and phone. A first-visit walkthrough, services with ' +
  'a wellness-exam checklist, three-tier wellness plan pricing with a comparison table, a vets page with a founder note, a ' +
  'patient gallery, FAQs and a booking form with the clinic details are all in place. Names, prices, hours and reviews are ' +
  'sample copy: swap in your own and publish. No lorem ipsum, no broken layouts. One simple commercial license, unlimited ' +
  'client sites.';
const PACK_SEO = {
  metaTitle: 'Wagtail: Veterinary Clinic Theme for Divi 5 (6 Pages) | Divi5Lab',
  metaDescription:
    'A complete six-page Divi 5 website theme for a vet clinic or pet grooming studio: Home, Services, Wellness Plans, Our ' +
    'Vets, The Clinic and Contact. One friendly brand, real copy, pricing and booking sections.',
  keywords: [
    'divi 5 veterinary theme', 'vet clinic website template', 'pet grooming divi template', 'animal hospital divi 5 theme',
    'veterinarian website template', 'divi 5 multi-page theme',
  ],
};

async function upsertPack(slugs: string[]): Promise<void> {
  const rows = await db
    .select({ id: layouts.id, slug: layouts.slug, previews: layouts.previewImageKeys })
    .from(layouts).where(inArray(layouts.slug, slugs));
  const bySlug = new Map(rows.map((r) => [r.slug, r]));
  const found = slugs.filter((s) => bySlug.has(s));
  if (found.length === 0) { console.error('no Wagtail pages found in DB — did ingest run?'); process.exitCode = 1; return; }
  if (found.length < slugs.length) console.warn(`only ${found.length}/${slugs.length} pages present; linking what exists`);

  const cover = bySlug.get(slugs[0])?.previews?.[0] ?? bySlug.get(found[0])!.previews?.[0] ?? null;
  const existing = (await db.select().from(packs).where(eq(packs.slug, PACK_SLUG)).limit(1))[0];
  const common = {
    title: PACK_TITLE, description: DESCRIPTION, kind: 'paid' as const,
    priceCents: PRICE_CENTS, stripePriceId: null, coverImageKey: cover, seo: PACK_SEO, status: 'published' as const,
  };
  let packId: string;
  if (existing) {
    packId = existing.id;
    await db.update(packs).set(common).where(eq(packs.id, packId));
  } else {
    packId = randomUUID();
    await db.insert(packs).values({ id: packId, slug: PACK_SLUG, ...common });
  }

  await db.delete(packLayouts).where(eq(packLayouts.packId, packId));
  await db.insert(packLayouts).values(found.map((s, i) => ({ packId, layoutId: bySlug.get(s)!.id, position: i })));

  console.log(`\nPack ready: /packs/${PACK_SLUG}  (paid, ${found.length} pages, cover=${cover ? 'set' : 'none'})`);
}

async function main() {
  const { deps, close } = await buildThemeDeps({ businessName: BRIEF.businessName, logPrefix: '[theme]', defaultMaxBudgetUsd: 1 });

  // Optional smoke-test knob: THEME_ONLY_ROLES=home,listings limits which pages generate.
  const onlyRoles = (process.env.THEME_ONLY_ROLES ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  const spec: ThemeSpec = onlyRoles.length ? { ...SPEC, pages: SPEC.pages.filter((p) => onlyRoles.includes(p.role)) } : SPEC;

  console.log(`[theme] generating ${spec.pages.length} ${spec.niche} pages for "${BRIEF.businessName}"…`);
  const result = await runThemePack(spec, deps);
  await close();
  console.log('[theme] summary:', { generated: result.generated, ingested: result.ingested, dropped: result.dropped, deduped: result.deduped });

  if (onlyRoles.length) { console.log('[theme] partial run (THEME_ONLY_ROLES set) — skipping pack assembly'); return; }
  const expectedSlugs = SPEC.pages.map((p) => themePageSlug(BRIEF, SPEC, p));
  await upsertPack(expectedSlugs);
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
